{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03", "C08", "C33", "C64", "C100", "C146", "C148", "C151", "C157", "C162"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C08", "C33", "C64", "C100", "C146"],
  "claims": [
    {
      "claim": "The closest structural context, AZD0837, which shares the benzyl amidoxime–azetidine amide core, has measured absolute oral bioavailability of 22–55% in humans; all reported values meet or exceed the 20% threshold.",
      "card_ids": ["C03", "C08", "C33", "C64"]
    },
    {
      "claim": "L3 enteral exposure data for AZD0837 in pigs show measurable systemic exposure after enteral dosing (control AUC0-6h 40.4 µmol·h/L; with ketoconazole 74.4 µmol·h/L), confirming that this chemotype is orally absorbed.",
      "card_ids": ["C100"]
    },
    {
      "claim": "L4 solubility data for the very close analog LB30889 (M19), which shares the same ethyl-glycine-azetidine-amidoxime scaffold, show solubility >500 µM at pH 7.4, indicating that solubility is not a barrier for this series.",
      "card_ids": ["C146"]
    },
    {
      "claim": "Related ester prodrugs such as perindopril, enalapril, and quinapril show moderate Caco-2 permeability and/or high solubility with high oral bioavailability, supporting that the ester prodrug motif can achieve F ≥20%.",
      "card_ids": ["C148", "C151", "C157", "C162"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C146", "C148", "C151", "C157", "C162"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the exact query molecule.",
    "AZD0837 differs from the query in the amidoxime O-substituent and acyl/ester region; transfer is analog-based.",
    "L4 provides solubility for a close analog but no direct permeability or efflux measurement for the query.",
    "The lower end of the AZD0837 F range (22%) is close to the 20% threshold.",
    "C100 is pig enteral data without an IV comparator, so it cannot quantify absolute bioavailability.",
    "C177 (dabigatran etexilate) shows that high solubility/permeability does not guarantee high F, but it is a different prodrug and not directly transferable."
  ],
  "decision_summary": "Prediction remains high (F ≥20%): the closest structural context AZD0837 has measured absolute oral bioavailability of 22–55% in humans, and L4 solubility data for a very close analog (LB30889, >500 µM at pH 7.4) plus related ester-prodrug permeability/solubility evidence support adequate absorption. Confidence remains moderate because the evidence is analog-based and the lower bound is near the threshold."
}

